head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLodingYn = 'N';
scwin.gDepCd;
scwin.gEmpNo;
scwin.questNo;
scwin.gIsurCd;
scwin.gParamObj = new Array(2);

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.cm.PanelToGroupBox(panel_Top1);
        scwin.gDepCd = js_dep_cd;
        scwin.gEmpNo = js_emp_no;

        // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
        // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
        const sbmOptions = {
            id : "sbm_dts_dep",
            action : "/CodeAction.do",
            ref : "",
            target : "dts_dep=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
        const sbmOptions2 = {
            id : "sbm_dts_emp",
            action : "/CodeAction.do",
            ref : "",
            target : "dts_emp=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.init();
        /*
        var getQuestNo= frame.Provider("../").fn_getQuestNo;
        questNo = getQuestNo();
         */

        await scwin.read();
        edt_SDate.setValue(dts_Quest.getCellData(dts_Quest.getRowPosition(), "QUEST_STRT_DD"));
        edt_EDate.setValue(dts_Quest.getCellData(dts_Quest.getRowPosition(), "QUEST_END_DD"));
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30323.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    scwin.questNo = $c.stf.getQuery(frame.srcUrl, "QUEST_NO");
    // alert('[questNo]'+questNo);

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Mail_onclick
 * @description 「메일발송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mail_onclick = async function() {
    try {
        await scwin.openSendMail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30323.btn_Mail_onclick" });
    }
};

/**
 * @method
 * @name grd_tmp_1_OnDblClick
 * @description grd_tmp_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_tmp_1_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "COM_NM") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30323.grd_tmp_1_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30323.txb_isur_cd_onblur" });
    }
};

