/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30323.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_depList_onselchange
 * @description cmb_depList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_depList_onselchange = function() {
    try {
        scwin.gDepCd = $c.stf.trim($c.cp.valueOfIndex(cmb_depList, "VALUE", cmb_depList.getSelectedIndex()));
        dts_emp.UseFilter = true;
        dts_emp.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30323.cmb_depList_onselchange" });
    }
};

