 */
scwin.dts_QuestResult_OnLoadCompleted = async function(rowcount) {
    try {
        if (scwin.gLodingYn === 'Y') {

        }
        if (dts_QuestResult.ErrorMsg) {
            await $c.win.alert(dts_QuestResult.ErrorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30323.dts_QuestResult_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Quest_OnLoadCompleted
 * @description dts_Quest 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Quest_OnLoadCompleted = async function(rowcount) {
    try {
        const isurCnt = dts_Quest.getCellData(dts_Quest.getRowPosition(), "ISUR_CD_CNT");
        const resultCnt = dts_Quest.getCellData(dts_Quest.getRowPosition(), "RESULT_CD_CNT");
        const noResultCnt = Number(isurCnt) - Number(resultCnt);
        const questRate = Number(resultCnt) / Number(isurCnt) * 100;
        // 비응답회사수
        dts_Quest.setCellData(dts_Quest.getRowPosition(), "NO_QUES_COM", noResultCnt);
        dts_Quest.setCellData(dts_Quest.getRowPosition(), "QUEST_RATE", scwin.roundMode(questRate, 1) + "%");
        const questStat = dts_Quest.getCellData(dts_Quest.getRowPosition(), "QUEST_STAT_CD");
        /*
        if(questStat == "0"){
        	questStat = "설문진행전(작성중)";
        }
        else if (questStat == "1") {
        	questStat = "설문종료";
        }
        else if (questStat == "3") {
        	questStat = "설문중지";
        }
        else if(questStat == "2"){
        	questStat = "설문진행중";
        }
        else{
        	questStat = "설문미진행";
        }
        txb_questStat.value = "(진행상태:  " + questStat + ")";
         */
        if (dts_Quest.getCellData(dts_Quest.getRowPosition(), "RESULT_CD_CNT") > 0) {
            // 응답회사가 있을경우 호출
            await scwin.quesInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30323.dts_Quest_OnLoadCompleted" });
    }
};

