    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30323.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Quest_Excel_onclick
 * @description 「설문결과 엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Quest_Excel_onclick = async function() {
    try {
        if (dts_Quest.getCellData(dts_Quest.getRowPosition(), "RESULT_CD_CNT") > 0) {
            $c.stf.doLogSave("ULDSTF30323.xml", SCREN_PROCS_TP_CD_07, '');
            $c.data.downloadGridViewExcel(grd_Grid, {fileName: "설문결과", type: "8"});
        } else {
            await $c.win.alert("[설문에 응답한 회사가] 없습니다.");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30323.btn_Quest_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
