/**
 * @method
 * @name roundMode
 * @description round Mode 처리
 * @param {*} v v
 * @param {*} scale scale
 * @returns {void}
 * @hidden N
 */
scwin.roundMode = function(v, scale) {
    const p = Math.pow(10, scale);
    return Math.round(v * p) / p;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (dts_QuestResult.getRowCount() === 0) {
        await $c.win.alert("대상을 선택하세요");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '저장'))) return;
    await scwin.trs();
};

